#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""САМОРАСПАКОВЩИК: хотфикс LLM + диагностика thinking.

Куда положить: в КОРЕНЬ проекта Джарвис (рядом с main.py и config.py).

    python jarvis_hotfix_bundle.py --list      # что внутри
    python jarvis_hotfix_bundle.py             # распаковать
    python jarvis_hotfix_bundle.py --force     # перезаписать существующие

После распаковки:
    python tests/check_llm.py            # какой способ отключает thinking
    python apply_hotfix_llm2.py --check  # проверка якорей, ничего не пишет
    python apply_hotfix_llm2.py          # применить

Внутри (проверено: py_compile, 17 функциональных тестов, идемпотентность,
откат, отказ ставиться поверх хотфикса v1):
    apply_hotfix_llm2.py   патч config.py + src/llm.py + src/tts.py
    tests/check_llm.py     диагностика /api/chat и /v1/chat/completions
"""

from __future__ import annotations

import base64
import sys
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent
FORCE = "--force" in sys.argv

PAYLOAD: dict[str, str] = {}

PAYLOAD["apply_hotfix_llm2.py"] = (
    ""
)

PAYLOAD["tests/check_llm.py"] = (
    ""
)


def main() -> int:
    if "--list" in sys.argv:
        for name, blob in sorted(PAYLOAD.items()):
            data = zlib.decompress(base64.b64decode(blob))
            print(f"  {name:28} {len(data):7d} байт  {len(data.decode().splitlines()):4d} строк")
        return 0

    if not (ROOT / "main.py").exists() or not (ROOT / "config.py").exists():
        print(f"\u274C {ROOT} не похоже на корень проекта Джарвис (нет main.py/config.py).")
        print("   Положите этот файл в корень проекта и запустите оттуда.")
        return 1

    written = skipped = 0
    for name, blob in sorted(PAYLOAD.items()):
        dest = ROOT / name
        data = zlib.decompress(base64.b64decode(blob))
        if dest.exists() and not FORCE:
            print(f"  \u00B7 {name}: уже существует (пропущен, --force чтобы перезаписать)")
            skipped += 1
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
        print(f"  \u2713 {name}  ({len(data)} байт)")
        written += 1

    print(f"\nРаспаковано: {written}, пропущено: {skipped}")
    print("\nДальше:")
    print("    python tests/check_llm.py")
    print("    python apply_hotfix_llm2.py --check")
    print("    python apply_hotfix_llm2.py")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
